using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OnEnemyOverCorruptedOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnEnemyOverCorrupted Omen Data")]
public class OnEnemyOverCorruptedOmenData : OmenData
{
	[Header("On Enemy Over Corrupted Omen")]
	protected Action<GameObject> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(GameObject overCorruptedEnemy)
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			ActivateOmen(overCorruptedEnemy);
		};
		SetMiscOmensHandlerOmenAction();
	}

	protected void SetMiscOmensHandlerOmenAction()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnEnemyOverCorruptedOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnEnemyOverCorruptedOmenActions.Remove(omenAction);
	}

	public override string OmenConvertedDescription()
	{
		return GetOverCorruptChantDescription() + base.OmenConvertedDescription();
	}

	protected string GetOverCorruptChantDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedOverCorruptChant() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace();
	}
}
